// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        c.seedMarket{value: 1 ether}(1 ether);
        address userA = makeAddr("userA");
        vm.prank(userA);
        c.getFreeKilo();
        vm.prank(userA);
        c.collectDrugs(address(this));
        vm.deal(userA, 10 ether);
        vm.prank(userA);
        c.buyDrugs{value: 1 ether}();
        uint256 marketDrugsBefore = c.marketDrugs();
        vm.prank(userA);
        c.sellDrugs();
        uint256 marketDrugsAfter = c.marketDrugs();
        assertTrue(marketDrugsAfter > marketDrugsBefore, "marketDrugs should increase after sell");
    }
}
